<script lang="ts">
 import MapCanvas from './MapCanvas.svelte';import Icon from './Icon.svelte';
 import {comparisonMetrics,MEMORY_DOMAIN_NOTE,summarizeVisual,type DashboardEvent} from './dashboard';
 import type {Json,WireFrame} from '../core';
 let {status,telemetry,frame,report,events,openDataset,openPerformance,runCommand}=$props<{status:Json;telemetry:Json;frame:WireFrame|null;report:Json|null;events:DashboardEvent[];openDataset:()=>void;openPerformance:()=>void;runCommand:(name:string,args?:Json)=>void}>();
 let rawView=$state('orbit'),semanticView=$state('orbit'),mapView=$state('top'),eventFilter=$state('all');
 const f=(n:any,d=1)=>typeof n==='number'&&Number.isFinite(n)?n.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
 const memory=(n:any)=>typeof n==='number'?n>=1073741824?f(n/1073741824,2)+' GB':f(n/1048576,1)+' MB':'—';
 let comparison=$derived(comparisonMetrics(report)),summary=$derived(summarizeVisual(frame));
 let rss=$derived(telemetry.processes?.some((p:Json)=>typeof p.rss_bytes==='number')?telemetry.processes.reduce((sum:number,p:Json)=>sum+(p.rss_bytes??0),0):null);
 let cards=$derived([{icon:'speed',label:'FPS',value:f(telemetry.fps),unit:'FPS',detail:'Runtime throughput'},{icon:'bolt',label:'End-to-End Latency',value:f(telemetry.latency_ms?.end_to_end?.p95),unit:'ms',detail:'Frame time · p95'},{icon:'chip',label:'Python Backend RSS',value:typeof rss==='number'?f(rss/1048576,0):'—',unit:'MB',detail:'Python runtime + mapper · excludes desktop shell'},{icon:'grid',label:'Active Cells',value:f(telemetry.map?.active_cells,0),unit:'',detail:'Live map leaves'},{icon:'database',label:'Memory Reduction vs Uniform Grid',value:f(comparison.memoryReduction),unit:'%',detail:comparison.memoryReduction===null?'Load a policy benchmark':'Benchmark peak-RSS comparison · not a live session'},{icon:'chart',label:'Semantic mIoU',value:f(report?.perception?.semantic?.miou),unit:report?.perception?.semantic?.miou==null?'':'%',detail:report?.perception?.semantic?.miou==null?'Requires semantic evaluation · benchmark, not live':'Benchmark mIoU · not a live session'}]);
 function width(value:any,reference:any){return typeof value==='number'&&typeof reference==='number'&&reference>0?Math.max(1,Math.min(100,value/reference*100)):0;}
</script>
<div class="dashboard">
 <div class="dashboard-metrics">{#each cards as card}<button class="dashboard-metric" onclick={openPerformance}><span class="metric-symbol"><Icon name={card.icon} size={25}/></span><div><h2>{card.label}</h2><div class="metric-number">{card.value}<small>{card.unit}</small></div><p>{card.detail}</p></div></button>{/each}</div>
 <div class="dashboard-map-grid">
  {#each [{title:'Raw LiDAR Point Cloud',icon:'cube',mode:'raw',cells:false},{title:'Semantic LiDAR',icon:'semantic',mode:'semantic',cells:false},{title:'Adaptive 2.5D Map',icon:'map',mode:'lod',cells:true}] as panel,i}
   <section class="dashboard-panel visualization-panel"><div class="dashboard-panel-title"><Icon name={panel.icon}/><h2>{panel.title}</h2><select aria-label={`${panel.title} camera`} value={i===0?rawView:i===1?semanticView:mapView} onchange={e=>{if(i===0)rawView=e.currentTarget.value;else if(i===1)semanticView=e.currentTarget.value;else mapView=e.currentTarget.value;}}><option value="orbit">3D View</option><option value="top">Top-Down</option><option value="driver">Driver</option></select></div>
    <div class="dashboard-map"><MapCanvas {frame} mode={panel.mode} showPoints={!panel.cells} showCells={panel.cells} boundaries={false} view={i===0?rawView:i===1?semanticView:mapView} follow={true}/>{#if !frame}<div class="dashboard-map-empty"><Icon name={panel.icon} size={34}/><strong>{panel.cells?'Adaptive map ready':'Waiting for LiDAR'}</strong><span>Open a dataset to begin a session.</span><button onclick={openDataset}>Choose dataset</button></div>{/if}{#if panel.cells}<div class="map-mini-legend">{#each [['#33d9f2','5 cm'],['#4dd980','10 cm'],['#ffb340','20 cm'],['#d966d9','40 cm']] as [color,label]}<span><i style:background={color}></i>{label}</span>{/each}</div>{/if}<div class="axis-marker"><span>Z</span><b>↑</b><small>Y ↗　→ X</small></div></div>
    {#if i===1}<div class="semantic-legend"><span><i style:background=" #388cfa"></i>Road</span><span><i style:background=" #f14d62"></i>Vehicle</span><span><i style:background=" #a457ec"></i>Person</span><span><i style:background=" #38b34c"></i>Terrain</span></div>{/if}
    <div class="visualization-caption">{#if panel.cells}<span>Cells: <b>{f(frame?.metadata.cells?.count,0)}</b></span><span>{status.policy?.replaceAll('_',' ')??'No policy'}</span>{:else}<span>Points: <b>{f(frame?.metadata.points?.count,0)}</b></span><span>{i===0?'World coordinates':`Semantic classes: ${summary.length||'—'}`}</span>{/if}</div>
   </section>
  {/each}
  <section class="dashboard-panel policy-panel"><div class="dashboard-panel-title"><Icon name="settings"/><h2>Resolution Policy</h2></div><table><thead><tr><th>Range</th><th>Cell Size</th><th>Logic</th></tr></thead><tbody>{#each [['Near Field','0–10 m','5 cm','Protected safety detail'],['Mid Field','10–30 m','10 cm','Balanced detail and efficiency'],['Outer Field','30–60 m','20 cm','Coarser mapping for large structures'],['Far Field','60–100 m','40 cm','Bounded distant terrain']] as row}<tr><td><strong>{row[0]}</strong><span>({row[1]})</span></td><td><strong>{row[2]}</strong></td><td>{row[3]}</td></tr>{/each}</tbody></table><div class="policy-utility"><h3><Icon name="bolt" size={18}/>Utility Promotion <span>Dynamic refinement</span></h3><ul><li>Motion evidence</li><li>Safety-critical obstacles</li><li>Terrain and elevation variation</li><li>Observation quality and confidence</li></ul><select aria-label="Dashboard resolution policy" value={status.policy??'distance_lod'} disabled={!status.frames} onchange={event=>runCommand('policy',{policy:event.currentTarget.value})}><option value="uniform5">Uniform 5 cm</option><option value="uniform40">Uniform 40 cm</option><option value="distance_lod">Distance LOD</option><option value="utility_lod">Utility LOD</option></select></div></section>
 </div>
 <div class="dashboard-bottom-grid">
  <section class="dashboard-panel comparison-panel"><div class="dashboard-panel-title"><Icon name="chart"/><h2>Uniform vs Adaptive Comparison</h2></div><div class="comparison-key"><span><i class="uniform"></i>Uniform 5 cm</span><span><i class="adaptive"></i>{comparison.adaptivePolicy}</span></div>{#each [{label:'Memory Usage',uniform:comparison.memoryUniform,adaptive:comparison.memoryAdaptive,memory:true},{label:'Map Latency p95',uniform:comparison.latencyUniform,adaptive:comparison.latencyAdaptive,memory:false}] as row}<div class="comparison-row"><strong>{row.label}</strong><div class="comparison-bars"><div><i class="uniform" style:width={`${width(row.uniform,row.uniform)}%`}></i><span>{row.memory?memory(row.uniform):f(row.uniform)+' ms'}</span></div><div><i class="adaptive" style:width={`${width(row.adaptive,row.uniform)}%`}></i><span>{row.memory?memory(row.adaptive):f(row.adaptive)+' ms'}</span></div></div></div>{/each}{#if !report}<p class="dashboard-footnote">Open a benchmark report to compare measured policy results.</p>{:else}<p class="dashboard-footnote">Benchmark measurements are separate from the live session. {MEMORY_DOMAIN_NOTE}</p>{/if}</section>
  <section class="dashboard-panel summary-panel"><div class="dashboard-panel-title"><Icon name="pie"/><h2>Object & Terrain Summary</h2></div><table><thead><tr><th>Semantic class</th><th>Points</th><th>Percentage</th></tr></thead><tbody>{#each summary.slice(0,6) as item}<tr><td><i class="summary-dot" style:background={['#99a9bb','#f14d62','#f6ac23','#f6ac23','#f14d62','#f14d62','#a457ec','#a457ec','#a457ec','#388cfa','#7188cf','#8fa9d4','#b8966f','#7b8a9e','#a2a0b6','#38b34c','#7b9950','#61ae57','#f6ac23','#e5b757'][item.id]??'#99a9bb'}></i>{item.name}</td><td>{f(item.count,0)}</td><td>{f(item.percent)}%</td></tr>{:else}{#each ['Road / drivable surface','Vehicles','People','Vegetation / terrain'] as name}<tr><td><i class="summary-dot"></i>{name}</td><td>—</td><td>—</td></tr>{/each}{/each}</tbody></table><p class="dashboard-footnote">{summary.length?'Displayed semantic points; counts are not tracked objects.':'Semantic observations unavailable.'}</p></section>
  <section class="dashboard-panel event-panel"><div class="dashboard-panel-title"><Icon name="file"/><h2>Event Log</h2><select aria-label="Event filter" bind:value={eventFilter}><option value="all">All Events</option><option value="error">Errors</option><option value="benchmark">Benchmarks</option></select></div><div class="event-list">{#each events.filter((e:DashboardEvent)=>eventFilter==='all'||e.kind===eventFilter).slice(-30).reverse() as event}<div class="event-item"><i class:error={event.kind==='error'}></i><time>{new Date(event.time).toLocaleTimeString(undefined,{hour12:false})}</time><p>{event.message}</p></div>{:else}<div class="events-empty">No runtime events yet.<span>Session changes and backend diagnostics appear here.</span></div>{/each}</div><p class="dashboard-footnote">Latest 200 events retained.</p></section>
 </div>
</div>
